/**
 * Standalone Server
 *
 * Standalone HTTP server for UI Bridge that can run independently.
 * Supports both HTTP and WebSocket connections.
 */

import type {
  UIBridgeServerConfig,
  UIBridgeServerHandlers,
  APIResponse,
  WebSocketMessage,
} from './types';
import { UI_BRIDGE_ROUTES } from './types';
import { UIBridgeWSHandler, type WebSocketLike } from './websocket-handler';
import { createWSStreamBroadcast } from './ws-stream-adapter';
import { SSEManager } from './sse-handler';
import type { BridgeEvent } from '../core';

/**
 * Standalone server configuration
 */
export interface StandaloneServerConfig extends UIBridgeServerConfig {
  /** Host to bind to */
  host?: string;
  /** Port to listen on */
  port?: number;
  /** Enable WebSocket support */
  websocket?: boolean;
  /** WebSocket port (defaults to port) */
  websocketPort?: number;
  /** Logging function */
  log?: (message: string) => void;
  /** Enable recording session support — pass the registry and optional changeObserver */
  recording?: {
    registry: import('../core/registry').UIBridgeRegistry;
    changeObserver?: import('../core/change-observer').ChangeObserver;
  };
}

/**
 * Default configuration
 */
const DEFAULT_CONFIG: Required<
  Pick<StandaloneServerConfig, 'host' | 'port' | 'websocket' | 'websocketPort' | 'log'>
> = {
  host: 'localhost',
  port: 9876,
  websocket: false,
  websocketPort: 9876,
  log: console.log,
};

/**
 * Wrap error in API format
 */
function wrapError(error: Error | string, code?: string): APIResponse<never> {
  return {
    success: false,
    error: typeof error === 'string' ? error : error.message,
    code,
    timestamp: Date.now(),
  };
}

/**
 * Simple HTTP server implementation using Node.js built-in http module
 * with optional WebSocket support.
 */
export class StandaloneServer {
  private server: import('http').Server | null = null;
  private wsServer: unknown = null; // WebSocket.Server from 'ws' package
  private config: Required<
    Pick<StandaloneServerConfig, 'host' | 'port' | 'websocket' | 'websocketPort' | 'log'>
  > &
    StandaloneServerConfig;
  private handlers: Partial<UIBridgeServerHandlers>;
  private wsHandler: UIBridgeWSHandler | null = null;
  private wsConnections: Set<WebSocketLike> = new Set();
  private sseManager: SSEManager;

  constructor(handlers: Partial<UIBridgeServerHandlers>, config: StandaloneServerConfig = {}) {
    this.handlers = handlers;
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.sseManager = new SSEManager();

    // Create WebSocket handler if enabled
    if (this.config.websocket) {
      this.wsHandler = new UIBridgeWSHandler(handlers as UIBridgeServerHandlers, {
        verbose: true,
        log: this.config.log,
        recording: this.config.recording,
      });
    }
  }

  /**
   * Get enabled capabilities based on handlers
   */
  private getCapabilities(): string[] {
    return [
      'elements',
      'components',
      'discovery',
      'navigation',
      'ai',
      'change_tracking',
      'idle_detection',
      'network',
      'forms',
      'design',
      'debug',
      'events',
      'annotations',
      'state_management',
      'clipboard',
      'undo_redo',
      'recovery',
      'intents',
    ];
  }

  /**
   * Start the server
   */
  async start(): Promise<void> {
    const http = await import('http');

    this.server = http.createServer(async (req, res) => {
      await this.handleRequest(req, res);
    });

    // Start WebSocket server if enabled
    if (this.config.websocket && this.wsHandler) {
      await this.startWebSocketServer();
    }

    return new Promise((resolve, reject) => {
      this.server!.listen(this.config.port, this.config.host, () => {
        this.config.log(
          `UI Bridge server listening on http://${this.config.host}:${this.config.port}`
        );
        if (this.config.websocket) {
          const wsPort = this.config.websocketPort || this.config.port;
          this.config.log(
            `UI Bridge WebSocket server listening on ws://${this.config.host}:${wsPort}`
          );
        }
        resolve();
      });

      this.server!.on('error', reject);
    });
  }

  /**
   * Start WebSocket server
   */
  private async startWebSocketServer(): Promise<void> {
    try {
      // Dynamically import ws package
      const { WebSocketServer } = await import('ws');

      const wsPort = this.config.websocketPort || this.config.port;
      const useSamePort = wsPort === this.config.port;

      if (useSamePort && this.server) {
        // Attach to same HTTP server (upgrade handling)
        this.wsServer = new WebSocketServer({ server: this.server });
      } else {
        // Create separate WebSocket server
        this.wsServer = new WebSocketServer({
          host: this.config.host,
          port: wsPort,
        });
      }

      const wss = this.wsServer as {
        on(event: 'connection', callback: (ws: WebSocketLike) => void): void;
        on(event: 'error', callback: (error: Error) => void): void;
        close(): void;
      };

      wss.on('connection', (ws) => {
        this.wsConnections.add(ws);
        this.wsHandler!.handleConnection(ws);

        ws.onclose = () => {
          this.wsConnections.delete(ws);
        };
      });

      wss.on('error', (error) => {
        this.config.log(`WebSocket server error: ${error.message}`);
      });
    } catch (_error) {
      // ws package not installed - WebSocket support disabled
      this.config.log(
        'Warning: WebSocket support requires the "ws" package. Install it with: npm install ws'
      );
      this.wsHandler = null;
    }
  }

  /**
   * Stop the server
   */
  async stop(): Promise<void> {
    // Close WebSocket handler
    if (this.wsHandler) {
      this.wsHandler.disconnectAll();
    }

    // Close WebSocket server
    if (this.wsServer) {
      const wss = this.wsServer as { close(): void };
      wss.close();
      this.wsServer = null;
    }

    // Close WebSocket connections
    for (const ws of this.wsConnections) {
      ws.close();
    }
    this.wsConnections.clear();

    // Close SSE manager
    this.sseManager.dispose();

    return new Promise((resolve, reject) => {
      if (!this.server) {
        resolve();
        return;
      }

      this.server.close((err) => {
        if (err) reject(err);
        else resolve();
      });
    });
  }

  /**
   * Handle an HTTP request
   */
  private async handleRequest(
    req: import('http').IncomingMessage,
    res: import('http').ServerResponse
  ): Promise<void> {
    const url = new URL(req.url || '/', `http://${req.headers.host}`);
    const method = req.method || 'GET';
    const basePath = this.config.basePath || '/ui-bridge';

    // Add CORS headers
    if (this.config.cors) {
      res.setHeader('Access-Control-Allow-Origin', '*');
      res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
      res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    }

    // Handle preflight
    if (method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }

    // Health check (also served at /status)
    if (url.pathname === '/health' || url.pathname === '/status') {
      const healthResponse: Record<string, unknown> = { status: 'ok', timestamp: Date.now() };

      // Include UI Bridge metadata for app discovery
      if (this.config.appInfo) {
        const uiBridge: Record<string, unknown> = {
          version: '0.3.0',
          ...this.config.appInfo,
          capabilities: this.getCapabilities(),
        };

        // Try to get element/component counts from handlers
        try {
          const snapshotResult = await this.handlers.getControlSnapshot?.();
          if (snapshotResult?.success && snapshotResult.data) {
            const data = snapshotResult.data as any;
            uiBridge.elementCount = data.elements?.length ?? 0;
            uiBridge.componentCount = data.components?.length ?? 0;
          }
        } catch {
          // Ignore - counts are optional
        }

        healthResponse.uiBridge = uiBridge;
      }

      this.sendJSON(res, healthResponse);
      return;
    }

    // Remove base path
    let path = url.pathname;
    if (path.startsWith(basePath)) {
      path = path.slice(basePath.length) || '/';
    }

    // SSE streaming endpoint — handled before normal routing
    if (path === '/control/events/stream' && method === 'GET') {
      res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
        'X-Accel-Buffering': 'no',
      });

      const types = url.searchParams.get('types') || undefined;
      const elements = url.searchParams.get('elements') || undefined;

      const clientId = this.sseManager.addClient(
        (data: string) => {
          res.write(data);
          return true;
        },
        () => {
          if (!res.writableEnded) res.end();
        },
        types,
        elements
      );

      req.on('close', () => {
        this.sseManager.removeClient(clientId);
      });
      return;
    }

    // Change observation SSE stream — filters to snapshot:changed events only
    if (path === '/control/changes/stream' && method === 'GET') {
      res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
        'X-Accel-Buffering': 'no',
      });

      const clientId = this.sseManager.addClient(
        (data: string) => {
          res.write(data);
          return true;
        },
        () => {
          if (!res.writableEnded) res.end();
        },
        'snapshot:changed'
      );

      req.on('close', () => {
        this.sseManager.removeClient(clientId);
      });
      return;
    }

    // Find matching route
    const route = this.findRoute(path, method);
    if (!route) {
      this.sendJSON(res, wrapError('Not found', 'NOT_FOUND'), 404);
      return;
    }

    try {
      // Parse body for POST/PUT/PATCH requests or when body is required
      let body: unknown = {};
      if (method === 'POST' || method === 'PUT' || method === 'PATCH' || route.bodyRequired) {
        body = await this.parseBody(req);
      }

      // Extract params
      const params = this.extractParams(path, route.path);

      // Get handler
      const handlerName = route.handler as keyof UIBridgeServerHandlers;
      const handler = this.handlers[handlerName];

      if (!handler) {
        this.sendJSON(res, wrapError('Not implemented', 'NOT_IMPLEMENTED'), 501);
        return;
      }

      // Build arguments
      const args: unknown[] = [];

      if (route.params) {
        for (const param of route.params) {
          args.push(params[param]);
        }
      }

      if (route.bodyRequired || method === 'POST' || method === 'PUT' || method === 'PATCH') {
        args.push(body);
      }

      if (method === 'GET') {
        const query = Object.fromEntries(url.searchParams);
        if (Object.keys(query).length > 0) {
          args.push(query);
        }
      }

      // Call handler
      const result = await (handler as (...args: unknown[]) => Promise<APIResponse<unknown>>)(
        ...args
      );
      this.sendJSON(res, result);
    } catch (error) {
      this.config.log(`Error handling ${method} ${path}: ${error}`);
      this.sendJSON(res, wrapError(error as Error, 'INTERNAL_ERROR'), 500);
    }
  }

  /**
   * Find a matching route
   */
  private findRoute(path: string, method: string): (typeof UI_BRIDGE_ROUTES)[0] | null {
    for (const route of UI_BRIDGE_ROUTES) {
      if (route.method !== method) continue;

      const routeRegex = route.path.replace(/:[^/]+/g, '([^/]+)').replace(/\//g, '\\/');

      const regex = new RegExp(`^${routeRegex}$`);
      if (regex.test(path)) {
        return route;
      }
    }
    return null;
  }

  /**
   * Extract params from path
   */
  private extractParams(path: string, routePath: string): Record<string, string> {
    const params: Record<string, string> = {};
    const routeParts = routePath.split('/');
    const pathParts = path.split('/');

    for (let i = 0; i < routeParts.length; i++) {
      if (routeParts[i].startsWith(':')) {
        params[routeParts[i].slice(1)] = pathParts[i];
      }
    }

    return params;
  }

  /**
   * Parse request body
   */
  private parseBody(
    req: import('http').IncomingMessage,
    maxBytes = 10 * 1024 * 1024
  ): Promise<unknown> {
    return new Promise((resolve, reject) => {
      let data = '';
      let bytes = 0;
      req.on('data', (chunk: string | Buffer) => {
        bytes += typeof chunk === 'string' ? Buffer.byteLength(chunk) : chunk.length;
        if (bytes > maxBytes) {
          req.destroy();
          reject(new Error('Request body too large'));
          return;
        }
        data += chunk;
      });
      req.on('end', () => {
        try {
          resolve(data ? JSON.parse(data) : {});
        } catch {
          resolve({});
        }
      });
      req.on('error', reject);
    });
  }

  /**
   * Send JSON response (safe against circular refs from DOM nodes)
   */
  private sendJSON(res: import('http').ServerResponse, data: unknown, status = 200): void {
    res.writeHead(status, { 'Content-Type': 'application/json' });
    const seen = new WeakSet();
    res.end(
      JSON.stringify(data, (_key, val) => {
        if (val !== null && typeof val === 'object') {
          if (typeof Node !== 'undefined' && val instanceof Node)
            return `[${val.constructor.name}]`;
          if (seen.has(val)) return '[Circular]';
          seen.add(val);
        }
        if (typeof val === 'function') return undefined;
        return val;
      })
    );
  }

  /**
   * Broadcast a message to all WebSocket connections (legacy)
   */
  broadcast(message: WebSocketMessage): void {
    const data = JSON.stringify(message);
    for (const ws of this.wsConnections) {
      if (ws.readyState === 1) {
        // OPEN
        ws.send(data);
      }
    }
  }

  /**
   * Broadcast an event to all subscribed WebSocket and SSE clients
   */
  broadcastEvent(event: BridgeEvent): void {
    if (this.wsHandler) {
      this.wsHandler.broadcastEvent(event);
    }
    this.sseManager.broadcast(event);
  }

  /**
   * Get the SSE manager for direct access (e.g., wiring to registry.onEvent)
   */
  getSSEManager(): SSEManager {
    return this.sseManager;
  }

  /**
   * Create an `onBrowserEvent` callback wired to the WS handler's broadcast.
   *
   * Call this **before** `createHandlers()` to get a callback you can pass as
   * `config.onBrowserEvent`. The internal BrowserEventStream in handlers.ts
   * will auto-subscribe and forward classified events through this callback
   * to all connected WebSocket clients.
   *
   * Returns `undefined` if WebSocket is not enabled, so it's safe to spread
   * into the config unconditionally.
   *
   * @example
   * ```ts
   * const server = new StandaloneServer({}, { websocket: true, port: 9876 });
   * const handlers = createHandlers(registry, executor, {
   *   onBrowserEvent: server.createBrowserEventCallback(),
   * });
   * ```
   */
  createBrowserEventCallback(): ((event: BridgeEvent) => void) | undefined {
    if (!this.wsHandler) {
      return undefined;
    }

    return createWSStreamBroadcast(this.wsHandler, { log: this.config.log });
  }

  /**
   * Create an `onChangeEvent` callback wired to SSE + WS broadcast.
   *
   * Call this **before** `createHandlers()` to get a callback you can pass as
   * `config.onChangeEvent`. The ChangeObserver in handlers.ts will forward
   * batched DOM change events through this callback to all connected clients.
   */
  createChangeEventCallback(): (event: BridgeEvent) => void {
    return (event: BridgeEvent) => {
      this.broadcastEvent(event);
    };
  }

  /**
   * Get WebSocket handler for direct access
   */
  getWSHandler(): UIBridgeWSHandler | null {
    return this.wsHandler;
  }

  /**
   * Get number of connected WebSocket clients
   */
  get wsClientCount(): number {
    return this.wsHandler?.clientCount ?? 0;
  }

  /**
   * Get the server address
   */
  getAddress(): { host: string; port: number } | null {
    const address = this.server?.address();
    if (!address || typeof address === 'string') return null;
    return { host: this.config.host, port: address.port };
  }
}

/**
 * Create and start a standalone server
 */
export async function createStandaloneServer(
  handlers: Partial<UIBridgeServerHandlers>,
  config?: StandaloneServerConfig
): Promise<StandaloneServer> {
  const server = new StandaloneServer(handlers, config);
  await server.start();
  return server;
}

/**
 * CLI entry point
 */
export async function startCLI(
  handlers: Partial<UIBridgeServerHandlers>,
  args: string[] = process.argv.slice(2)
): Promise<void> {
  const config: StandaloneServerConfig = {};

  // Parse CLI args
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    const nextArg = args[i + 1];

    if (arg === '--port' || arg === '-p') {
      config.port = parseInt(nextArg);
      i++;
    } else if (arg === '--host' || arg === '-h') {
      config.host = nextArg;
      i++;
    } else if (arg === '--cors') {
      config.cors = true;
    }
  }

  const server = await createStandaloneServer(handlers, config);

  // Handle shutdown
  process.on('SIGINT', async () => {
    console.log('\nShutting down...');
    await server.stop();
    process.exit(0);
  });

  process.on('SIGTERM', async () => {
    await server.stop();
    process.exit(0);
  });
}
